    {"path": "cuphead-trainer/src/memory_reader.py", "content": "import ctypes\nimport sys\nfrom ctypes import wintypes\n\nclass MemoryReader:\n    \"\"\"Reads process memory for Cuphead (Windows only).\n    Uses kernel32 ReadProcessMemory via ctypes.\n    \"\"\"\n    def __init__(self, process_name: str = \"Cuphead.exe\"):\n        self.process_name = process_name\n        self.process_handle = None\n        self._load_kernel32()\n\n    def _load_kernel32(self):\n        if sys.platform != \"win32\":\n            raise OSError(\"MemoryReader only works on Windows\")\n        self.kernel32 = ctypes.WinDLL(\"kernel32\", use_last_error=True)\n        self.kernel32.OpenProcess.argtypes = [wintypes.DWORD, wintypes.BOOL, wintypes.DWORD]\n        self.kernel32.OpenProcess.restype = wintypes.HANDLE\n        self.kernel32.ReadProcessMemory.argtypes = [wintypes.HANDLE, wintypes.LPCVOID, wintypes.LPVOID, ctypes.c_size_t, ctypes.POINTER(ctypes.c_size_t)]\n        self.kernel32.ReadProcessMemory.restype = wintypes.BOOL\n        self.kernel32.CloseHandle.argtypes = [wintypes.HANDLE]\n        self.kernel32.CloseHandle.restype = wintypes.BOOL\n\n    def _find_process_id(self) -> int:\n        import psutil\n        for proc in psutil.process_iter(['pid', 'name']):\n            if proc.info['name'] == self.process_name:\n                return proc.info['pid']\n        raise ProcessLookupError(f\"{self.process_name} not found\")\n\n    def open(self):\n        pid = self._find_process_id()\n        PROCESS_VM_READ = 0x0010\n        self.process_handle = self.kernel32.OpenProcess(PROCESS_VM_READ, False, pid)\n        if not self.process_handle:\n            raise ctypes.WinError(ctypes.get_last_error())\n\n    def read_int(self, address: int) -> int:\n        \"\"\"Read a 4-byte integer from the given address.\"\"\"\n        buffer = (ctypes.c_uint8 * 4)()\n        bytes_read = ctypes.c_size_t(0)\n        ret = self.kernel32.ReadProcessMemory(self.process_handle, ctypes.c_void_p(address), buffer, 4, ctypes.byref(bytes_read))\n        if not ret or bytes_read.value != 4:\n            raise RuntimeError(f\"Failed to read memory at {hex(address)}\")\n        return int.from_bytes(bytes(buffer), byteorder='little')\n\n    def read_float(self, address: int) -> float:\n        \"\"\"Read a 4-byte float from the given address.\"\"\"\n        int_val = self.read_int(address)\n        import struct\n        return struct.unpack('f', struct.pack('I', int_val))[0]\n\n    def close(self):\n        if self.process_handle:\n            self.kernel32.CloseHandle(self.process_handle)\n            self.process_handle = None\n"},
    {"path": "cuphead-trainer/src/trainer_core.py", "content": "from src.memory_reader import MemoryReader\n\nclass TrainerCore:\n    \"\"\"Core trainer logic for Cuphead: infinite lives, coins, etc.\n    Known offsets (example) for game version 1.3.4:\n      - Lives: 0x00A1B2C0\n      - Coins: 0x00A1B2C4\n    \"\"\"\n    def __init__(self):\n        self.reader = MemoryReader()\n        self._offsets = {\n            \"lives\": 0x00A1B2C0,\n            \"coins\": 0x00A1B2C4,\n            \"health\": 0x00A1B2C8,\n        }\n        self._active = False\n\n    def connect(self):\n        \"\"\"Connect to the Cuphead process.\"\"\"\n        self.reader.open()\n        self._active = True\n\n    def disconnect(self):\n        \"\"\"Disconnect from the process.\"\"\"\n        self.reader.close()\n        self._active = False\n\n    @property\n    def is_active(self) -> bool:\n        return self._active\n\n    def get_lives(self) -> int:\n        \"\"\"Read current lives count.\"\"\"\n        if not self._active:\n            raise RuntimeError(\"Not connected to process\")\n        return self.reader.read_int(self._offsets[\"lives\"])\n\n    def get_coins(self) -> int:\n        \"\"\"Read current coin count.\"\"\"\n        if not self._active:\n            raise RuntimeError(\"Not connected to process\")\n        return self.reader.read_int(self._offsets[\"coins\"])\n\n    def get_health(self) -> float:\n        \"\"\"Read current health as float.\"\"\"\n        if not self._active:\n            raise RuntimeError(\"Not connected to process\")\n        return self.reader.read_float(self._offsets[\"health\"])\n\n    def set_lives(self, value: int):\n        \"\"\"Write lives value (placeholder - would need WriteProcessMemory).\"\"\"\n        # In a real trainer, write to memory here\n        raise NotImplementedError(\"Write support not implemented in this demo\")\n"},
    {"path": "cuphead-trainer/src/hotkey_listener.py", "content": "from pynput import keyboard\nimport threading\n\nclass HotkeyListener:\n    \"\"\"Listens for global hotkeys to toggle trainer features.\n    Default: F1 = infinite lives, F2 = add coins, F3 = exit.\n    \"\"\"\n    def __init__(self, trainer_core):\n        self.trainer = trainer_core\n        self._listener = None\n        self._running = False\n        self._callbacks = {\n            \"<f1>\": self._toggle_infinite_lives,\n            \"<f2>\": self._add_coins,\n            \"<f3>\": self._exit_trainer,\n        }\n        self._infinite_lives = False\n\n    def _toggle_infinite_lives(self):\n        self._infinite_lives = not self._infinite_lives\n        status = \"ON\" if self._infinite_lives else \"OFF\"\n        print(f\"[Hotkey] Infinite lives: {status}\")\n        # In a real trainer, would start a thread to continuously set lives\n\n    def _add_coins(self):\n        print(\"[Hotkey] Adding 99 coins (placeholder)\")\n        # Would call trainer.set_coins(...)\n\n    def _exit_trainer(self):\n        print(\"[Hotkey] Exiting trainer...\")\n        self.stop()\n\n    def _on_press(self, key):\n        try:\n            if hasattr(key, 'char') and key.char:\n                return\n            key_name = str(key).lower()\n            if key_name in self._callbacks:\n                self._callbacks[key_name]()\n        except Exception as e:\n            print(f\"[Hotkey] Error: {e}\")\n\n    def start(self):\n        \"\"\"Start listening for hotkeys in a background thread.\"\"\"\n        if self._running:\n            return\n        self._running = True\n        self._listener = keyboard.Listener(on_press=self._on_press)\n        self._listener.start()\n        print(\"[Hotkey] Listener started. Press F1 (infinite lives), F2 (add coins), F3 (exit).\")\n\n    def stop(self):\n        \"\"\"Stop the listener.\"\"\"\n        if self._listener:\n            self._listener.stop()\n        self._running = False\n        self.trainer.disconnect()\n"},
    {"path": "cuphead-trainer/main.py", "content": "from src.trainer_core import TrainerCore\nfrom src.hotkey_listener import HotkeyListener\nimport time\n\ndef main():\n    \"\"\"Entry point for Cuphead Trainer.\"\"\"\n    print(\"=== Cuphead Trainer v1.0 ===\")\n    print(\"Make sure Cuphead.exe is running.\")\n    \n    trainer = TrainerCore()\n    try:\n        trainer.connect()\n        print(f\"Connected. Lives: {trainer.get_lives()}, Coins: {trainer.get_coins()}, Health: {trainer.get_health():.1f}\")\n    except Exception as e:\n        print(f\"Failed to connect: {e}\")\n        return\n\n    listener = HotkeyListener(trainer)\n    listener.start()\n\n    try:\n        while listener._running:\n            time.sleep(0.5)\n            # In a real trainer, continuously apply cheats here\n    except KeyboardInterrupt:\n        print(\"\\nInterrupted by user.\")\n    finally:\n        listener.stop()\n        print(\"Trainer exited.\")\n\nif __name__ == \"__main__\":\n    main()\n"},
