    {"path": "cuphead-trainer/tests/test_trainer_core.py", "content": "import pytest\nfrom src.trainer_core import TrainerCore\n\ndef test_trainer_core_initialization():\n    \"\"\"Test that TrainerCore initializes without error.\"\"\"\n    trainer = TrainerCore()\n    assert trainer.is_active == False\n    assert trainer._offsets[\"lives\"] == 0x00A1B2C0\n\ndef test_trainer_core_connect_fails_no_process():\n    \"\"\"Connecting without Cuphead running should raise.\"\"\"\n    trainer = TrainerCore()\n    with pytest.raises((ProcessLookupError, OSError)):\n        trainer.connect()\n\ndef test_trainer_core_get_methods_raise_when_not_connected():\n    \"\"\"Calling get_* without connection should raise RuntimeError.\"\"\"\n    trainer = TrainerCore()\n    with pytest.raises(RuntimeError, match=\"Not connected\"):\n        trainer.get_lives()\n    with pytest.raises(RuntimeError, match=\"Not connected\"):\n        trainer.get_coins()\n    with pytest.raises(RuntimeError, match=\"Not connected\"):\n        trainer.get_health()\n\ndef test_hotkey_listener_import():\n    \"\"\"Verify HotkeyListener can be imported.\"\"\"\n    from src.hotkey_listener import HotkeyListener\n    assert HotkeyListener is not None\n"}
